function processValue(value: string | number) {
  if (typeof value === 'string') {
    // TypeScript knows value is string here
    return value.toUpperCase();
  }
  // TypeScript knows value is number here
  return value.toFixed(2);
}

class ApiError extends Error {
  constructor(public statusCode: number, message: string) {
    super(message);
  }
}

function handleError(error: Error | ApiError) {
  if (error instanceof ApiError) {
    console.log(error.statusCode); // Access ApiError properties
  }
  console.log(error.message); // Both have message
}

interface User {
  type: 'user';
  name: string;
}

interface Admin {
  type: 'admin';
  name: string;
  permissions: string[];
}

type Account = User | Admin;

// Custom type guard
function isAdmin(account: Account): account is Admin {
  return account.type === 'admin';
}

function handleAccount(account: Account) {
  if (isAdmin(account)) {
    console.log(account.permissions); // TypeScript knows it's Admin
  }
}
